<?php
declare(strict_types=1);header('Cache-Control: no-store');require_once __DIR__.'/../src/auth.php';require_once __DIR__.'/../src/permissions.php';$user=auth_require_login();require_role('ADMIN');$today=date('Y-m-d');?>
<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>VF-Tagesexport C4</title><link rel="stylesheet" href="app.css"></head><body>
<div class="card"><div class="row"><strong>Angemeldet: <?=htmlspecialchars((string)$user['display_name'],ENT_QUOTES,'UTF-8')?></strong><a class="button secondary" href="vf_export_journal.php">Exportjournal</a><a class="button secondary" href="dashboard.php">Dashboard</a></div></div>
<h1>VF-Tagesexport</h1><p class="info">Produktionsnaher Tagesexport mit neuer Vorschau vor jedem Lauf, maximal 50 Flügen, Einzelergebnis je Flug und Abstimmungsstatus bei duplicateflid.</p>
<div class="card"><div class="row"><label>Flugdatum <input id="date" type="date" value="<?=$today?>"></label><button id="preview">Vorschau laden</button><button id="all" disabled>Alle sendbaren auswählen</button></div><p><label><input id="confirm" type="checkbox"> Ich habe alle ausgewählten Flüge, Personen, Sonderfälle und Payloads geprüft.</label></p><button id="send" class="ok" disabled>Tagesexport starten</button></div><div id="out" class="card">Noch keine Vorschau.</div>
<script>'use strict';const csrf=<?=json_encode(csrf_token())?>,out=document.getElementById('out');let items=[],busy=false;const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));async function api(b){const r=await fetch('api_vf_day_export.php?v=c4',{method:'POST',cache:'no-store',headers:{'Content-Type':'application/json'},body:JSON.stringify({...b,csrf_token:csrf})});const t=await r.text();let d;try{d=JSON.parse(t)}catch(x){throw new Error(t.slice(0,180))}if(!r.ok||!d.ok)throw new Error(d.error||'HTTP '+r.status);return d}function ids(){return Array.from(document.querySelectorAll('.pick:checked')).map(x=>+x.value)}function upd(){document.getElementById('send').disabled=busy||!document.getElementById('confirm').checked||ids().length===0}function table(){return `<table><tr><th>Auswahl</th><th>ID</th><th>Flug</th><th>Zeit</th><th>Prüfung</th></tr>${items.map(i=>`<tr><td>${i.send_allowed?`<input class="pick" type="checkbox" value="${i.entry_id}">`:'Gesperrt'}</td><td>${i.entry_id}</td><td>${e(i.callsign)}<br>${e(i.pilot)}</td><td>${e(i.departuretime)}<br>${e(i.arrivaltime)}</td><td>${i.issues.length?'<div class="warnbox">'+i.issues.map(e).join('<br>')+'</div>':'<div class="okbox">Sendbar</div>'}<details><summary>Payload</summary><pre>${e(JSON.stringify(i.payload,null,2))}</pre></details></td></tr>`).join('')}</table>`}async function preview(){busy=true;upd();out.textContent='Vorschau wird geladen …';try{const d=await api({action:'preview',date:document.getElementById('date').value});items=d.items;out.innerHTML=`<div class="grid"><div class="metric"><b>${d.candidate_count}</b><span>Kandidaten</span></div><div class="metric"><b>${d.sendable_count}</b><span>sendbar</span></div><div class="metric"><b>${d.blocked_count}</b><span>blockiert</span></div></div>${table()}`;document.querySelectorAll('.pick').forEach(x=>x.addEventListener('change',upd));document.getElementById('all').disabled=d.sendable_count===0}catch(x){out.innerHTML='<div class="warnbox">'+e(x.message)+'</div>'}finally{busy=false;upd()}}async function send(){const a=ids();if(!a.length||!document.getElementById('confirm').checked||busy)return;if(!confirm(`${a.length} Flüge als Tagesexport senden?`))return;busy=true;upd();out.textContent='Tagesexport läuft …';try{const d=await api({action:'run',date:document.getElementById('date').value,entry_ids:a,confirm_day_export:true});const r=d.result;out.innerHTML=`<h2>Lauf ${r.run_id}</h2><p>${r.successful} erfolgreich, ${r.failed} fehlgeschlagen, ${r.reconciliation_required} Abstimmung erforderlich.</p><table><tr><th>ID</th><th>Status</th><th>VF-flid</th><th>Hinweis</th></tr>${r.items.map(i=>`<tr><td>${i.entry_id}</td><td>${e(i.status)}</td><td>${e(i.flid)}</td><td>${e(i.error)}</td></tr>`).join('')}</table><p>Vor weiterem Export neue Vorschau laden.</p>`;items=[]}catch(x){out.innerHTML='<div class="warnbox">'+e(x.message)+'</div>'}finally{busy=false;upd()}}document.getElementById('preview').onclick=preview;document.getElementById('all').onclick=()=>{document.querySelectorAll('.pick').forEach(x=>x.checked=true);upd()};document.getElementById('confirm').onchange=upd;document.getElementById('send').onclick=send;</script></body></html>
